// @ts-check
/// <reference path="../kino.d.ts" />
// HDFull (personal, local): movies and series that HDFull hosts on captcha-free servers (vidmoly, streamtape, mixdrop).
// Copies on captcha servers (powvideo, streamplay, waaw) are never listed: a title or episode with only those is left out.
//
// The plugin carries only ids and video codes (MOVIES and SERIES below, generated by build_plugin_data.py);
// everything shown (titles, posters, overviews, genres, episode names) comes live from TMDB through kino.tmdb.
//
// Refs:  m:<tmdbId>   m:i<imdbDigits> (no TMDB id known at build time: resolved live with /find)
//        s:<tmdbTvId>                 a series (episodes lists only the episodes in the index)
//        e:<tmdbTvId>:<season>:<ep>   one episode
//        c:<slot>     one video code as an alternative copy (slot = <lang><host><code>)
//        browse:<list> | browse:genre:<genreId> | browse:recent | browse:recentTv
//
// Read top to bottom: 1. texts  2. index  3. TMDB  4. rows/browse/search/details/episodes  5. resolvers  6. resolve

// ---- 1. texts ----

const T = {
  es: {
    recent: "Películas agregadas a HDFull",
    recentTv: "Series agregadas a HDFull",
    trending: "Películas en tendencia",
    trendingTv: "Series en tendencia",
    popular: "Películas populares",
    popularTv: "Series populares",
    topRated: "Películas mejor valoradas",
    topRatedTv: "Series mejor valoradas",
    nowPlaying: "Estrenos",
    genre: "Películas de",
    episode: "Episodio",
    noStreams: "Este título no tiene una copia que cargue ahora.",
    notFound: "No encontramos ese título.",
    tmdbDown: "No se pudo consultar el catálogo. Revisa tu conexión e inténtalo de nuevo.",
    lang: { E: "Castellano", L: "Latino", S: "Subtitulado", O: "Original" },
    status: (m, s, e) => `${m} películas, ${s} series (${e} episodios)`,
  },
  en: {
    recent: "Movies added to HDFull",
    recentTv: "Series added to HDFull",
    trending: "Trending movies",
    trendingTv: "Trending series",
    popular: "Popular movies",
    popularTv: "Popular series",
    topRated: "Top rated movies",
    topRatedTv: "Top rated series",
    nowPlaying: "New releases",
    genre: "Movies:",
    episode: "Episode",
    noStreams: "This title has no copy that loads right now.",
    notFound: "We could not find that title.",
    tmdbDown: "Could not load the catalog. Check your connection and try again.",
    lang: { E: "Spanish (Spain)", L: "Latin American Spanish", S: "Subtitled", O: "Original" },
    status: (m, s, e) => `${m} movies, ${s} series (${e} episodes)`,
  },
};
const isEs = () => kino.language !== "en";
const t = (k) => (isEs() ? T.es : T.en)[k];

function cfg(key, fallback) {
  try {
    const v = kino.config.get(key);
    return v === null || v === undefined || v === "" ? fallback : v;
  } catch { return fallback; }
}

