/** @type {Map<string, string[]> | null} */
let byId = null;
/** @type {string[]} */
let order = [];

function index() {
  if (byId) return byId;
  byId = new Map();
  order = [];
  for (const line of MOVIES.split("\n")) {
    const i = line.indexOf(":");
    if (i <= 0) continue;
    const id = line.slice(0, i);
    byId.set(id, line.slice(i + 1).split(","));
    order.push(id);
  }
  return byId;
}
const has = (tmdbId) => liveCodes(index().get(String(tmdbId))).length > 0;

/** Series lines, split per show on demand (a show's episodes are parsed only when asked). */
/** @type {Map<string, string> | null} */
let tvRaw = null;
/** @type {string[]} */
let tvOrder = [];
function tvIndex() {
  if (tvRaw) return tvRaw;
  tvRaw = new Map();
  tvOrder = [];
  for (const line of SERIES.split("\n")) {
    const i = line.indexOf(":");
    if (i <= 0) continue;
    const id = line.slice(0, i);
    tvRaw.set(id, line.slice(i + 1));
    tvOrder.push(id);
  }
  return tvRaw;
}
const hasTv = (tmdbId) => tvIndex().has(String(tmdbId)) && [...showEpisodes(tmdbId).values()].some((c) => liveCodes(c).length > 0);

/** "S.E" -> codes, for one show. */
function showEpisodes(id) {
  const raw = tvIndex().get(String(id));
  /** @type {Map<string, string[]>} */
  const out = new Map();
  if (!raw) return out;
  for (const part of raw.split(";")) {
    const eq = part.indexOf("=");
    if (eq > 0) out.set(part.slice(0, eq), part.slice(eq + 1).split(","));
  }
  return out;
}

// A copy that failed to play is remembered 30 days (the host deleted the file: HDFull still links it), so it is not
// tried again, and a title or episode whose copies all failed leaves the lists. Only real play attempts feed it.
const DEAD_MS = 30 * 24 * 3600 * 1000;
/** @type {Set<string> | null} */
let deadSet = null;
function dead() {
  if (deadSet) return deadSet;
  try { deadSet = new Set(JSON.parse(kino.storage.get("dead") || "[]")); } catch { deadSet = new Set(); }
  return deadSet;
}
function markDead(slot) {
  const d = dead();
  if (d.has(slot)) return;
  d.add(slot);
  // ~16 bytes a slot: a few thousand fit in kino.storage next to the TMDB copies.
  try { kino.storage.set("dead", JSON.stringify([...d].slice(-6000)), { ttlMs: DEAD_MS }); } catch { /* full: forget */ }
}
const liveCodes = (codes) => (codes || []).filter((c) => !dead().has(c));

// vidmoly says "not found" both for a deleted file and to an IP that asked too much: one such answer only makes the
// copy suspect; a second one at least an hour later makes it dead. A copy that plays again stops being suspect.
const SUSPECT_GAP_MS = 3600 * 1000;
function suspects() {
  try { return JSON.parse(kino.storage.get("suspect") || "{}"); } catch { return {}; }
}
function saveSuspects(all) {
  try { kino.storage.set("suspect", JSON.stringify(all), { ttlMs: DEAD_MS }); } catch { /* full: forget */ }
}
/** One failed play of [slot]: dead now, dead on a second suspect failure, or nothing (network trouble). */
function noteFailure(slot, e) {
  if (gone(e)) { markDead(slot); return; }
  if (!suspect(e)) return;
  const all = suspects();
  const first = all[slot];
  if (first && Date.now() - first >= SUSPECT_GAP_MS) {
    delete all[slot];
    saveSuspects(all);
    markDead(slot);
  } else if (!first) {
    all[slot] = Date.now();
    saveSuspects(all);
  }
}
function notePlayed(slot) {
  const all = suspects();
  if (all[slot]) { delete all[slot]; saveSuspects(all); }
}

// ---- 3. TMDB (live, through Kino) ----

const IMG = "https://image.tmdb.org/t/p/";
const img = (size, p) => (p ? IMG + size + p : undefined);
const lang = () => (isEs() ? "es-MX" : "en-US");
const year = (d) => (typeof d === "string" && /^\d{4}/.test(d) ? Number(d.slice(0, 4)) : undefined);

async function tmdb(path, params = {}) {
  try {
    return await kino.tmdb(path, { language: lang(), ...params });
  } catch (e) {
    if (e && e.code === "not_found") throw kino.error("not_found", "tmdb 404 " + path, { userMessage: t("notFound") });
    if (e && e.userMessage) throw e;
    throw kino.error("unavailable", "tmdb " + path + " " + (e && e.code), { userMessage: t("tmdbDown") });
  }
}

// kino.tmdb answers 20 calls per 10 s per plugin on Kino's key (40 with the person's own): a slim copy of each
// title (14 days) and of each filtered list page (6 h) lives in kino.storage (256 KB), so a reopened Home costs nothing.
const DAY = 24 * 3600 * 1000;
function cacheGet(key) {
  try { const v = kino.storage.get(key); return v ? JSON.parse(v) : null; } catch { return null; }
}
function cacheSet(key, value, ttlMs) {
  try { kino.storage.set(key, JSON.stringify(value), { ttlMs }); } catch { /* storage full: no copy */ }
}
/** Only what a card needs; `tv` marks a series. */
const slim = (m, tv) => ({ id: m.id, tv: tv ? 1 : 0, title: (tv ? m.name || m.original_name : m.title || m.original_title) || "",
  poster_path: m.poster_path, backdrop_path: m.backdrop_path, date: tv ? m.first_air_date : m.release_date,
  vote_average: m.vote_average });

/** A card from a slim title (movie or series). */
function card(m, ref) {
  const tv = !!m.tv;
  return {
    id: (tv ? "s" : "m") + m.id,
    ref: ref || (tv ? "s:" : "m:") + m.id,
    title: m.title,
    kind: /** @type {"movie" | "series"} */ (tv ? "series" : "movie"),
    year: year(m.date),
    poster: img("w342", m.poster_path),
    backdrop: img("w780", m.backdrop_path),
    rating: m.vote_average ? Math.round(m.vote_average * 10) / 10 : undefined,
    ids: { tmdb: m.id },
    badges: tv ? tvBadges(String(m.id)) : badges(String(m.id)),
  };
}

const CHIPS = { E: "CAST", L: "LAT", S: "SUB", O: "VO" };
const chips = (langs) => {
  const seen = [...langs].map((l) => CHIPS[l]).filter(Boolean);
  return seen.length ? seen.slice(0, 3) : undefined;
};
/** Language chips for a movie: "CAST", "LAT", "SUB". */
const badges = (id) => chips(new Set((index().get(id) || []).map((c) => c[0])));
/** For a series: every language any of its episodes has. */
function tvBadges(id) {
  const raw = tvIndex().get(id) || "";
  return chips(new Set([...raw.matchAll(/[=,]([ELSO])[vsm]/g)].map((m) => m[1])));
}

/** A slim TMDB movie for one index id ("123" or "i<imdb>"), or null. */
async function movieFor(id) {
  const key = `mv:${lang()}:${id}`;
  const hit = cacheGet(key);
  if (hit) return hit;
  let m = null;
  try {
    if (id[0] !== "i") m = await tmdb("/movie/" + id);
    else m = ((await tmdb("/find/tt" + id.slice(1), { external_source: "imdb_id" })).movie_results || [])[0] || null;
  } catch { return null; }
  if (!m) return null;
  const s = slim(m, false);
  cacheSet(key, s, 14 * DAY);
  return s;
}

/** A slim TMDB series, or null. */
async function showFor(id) {
  const key = `tv:${lang()}:${id}`;
  const hit = cacheGet(key);
  if (hit) return hit;
  let m = null;
  try { m = await tmdb("/tv/" + id); } catch { return null; }
  const s = slim(m, true);
  cacheSet(key, s, 14 * DAY);
  return s;
}

/** One TMDB list page reduced to the titles in the index (cached 6 h). */
async function listPage(path, params, page, tv) {
  const key = `pg:${lang()}:${path}:${JSON.stringify(params)}:${page}`;
  const hit = cacheGet(key);
  if (hit) return hit;
  const data = await tmdb(path, { ...params, page });
  const out = { total: Math.min(data.total_pages || 1, 500),
    hits: (data.results || []).filter((m) => m.poster_path && (tv ? hasTv(m.id) : has(m.id))).map((m) => slim(m, tv)) };
  cacheSet(key, out, DAY / 4);
  return out;
}

// ---- 4. rows / browse / search / details / episodes ----

const LISTS = {
  trending: { path: "/trending/movie/week", key: "trending" },
  trendingTv: { path: "/trending/tv/week", key: "trendingTv", tv: true },
  popular: { path: "/movie/popular", key: "popular" },
  popularTv: { path: "/tv/popular", key: "popularTv", tv: true },
  now: { path: "/movie/now_playing", key: "nowPlaying" },
  top: { path: "/movie/top_rated", key: "topRated" },
  topTv: { path: "/tv/top_rated", key: "topRatedTv", tv: true },
};
const PAGE = 20;
const MAX_TMDB_PAGES = 6;
// TMDB calls a cold Home may make: 7 + 7 recent titles + 4 list pages = 18, under Kino's 20 per 10 s.
const HOME_RECENT = 7;
const HOME_LISTS = ["trending", "trendingTv", "popular", "popularTv"];

/** Walks TMDB pages from [startPage], keeping only titles in the index, until [PAGE] items or the cap. */
async function filtered(path, params, startPage, tv, maxPages = MAX_TMDB_PAGES) {
  const items = [];
  let page = startPage;
  let total = 1;
  for (let n = 0; n < maxPages && items.length < PAGE; n++, page++) {
    const data = await listPage(path, params, page, tv);
    total = data.total;
    for (const m of data.hits) items.push(card(m));
    if (page >= total) return { items, next: undefined };
  }
  return { items, next: String(page) };
}

/** The index's own order (newest first), one page, details from TMDB live. */
async function recent(cursor, size, tv) {
  if (tv) tvIndex(); else index();
  const ids = tv ? tvOrder : order;
  const from = Math.max(0, parseInt(cursor || "0", 10) || 0);
  const slice = ids.slice(from, from + size).filter((id) => (tv ? hasTv(id) : liveCodes(index().get(id)).length > 0));
  const found = await Promise.all(slice.map(tv ? showFor : movieFor));
  const items = [];
  found.forEach((m, i) => { if (m && m.poster_path) items.push(card(m, (tv ? "s:" : "m:") + slice[i])); });
  return { items, next: from + size < ids.length ? String(from + size) : undefined };
}

export async function home() {
  const defs = [
    ["recent", () => recent(null, HOME_RECENT, false)],
    ["recentTv", () => recent(null, HOME_RECENT, true)],
    ...HOME_LISTS.map((id) => [id, () => filtered(LISTS[id].path, {}, 1, !!LISTS[id].tv, 1)]),
  ];
  const settled = await Promise.allSettled(defs.map(([, fn]) => fn()));
  const rows = [];
  settled.forEach((r, i) => {
    if (r.status !== "fulfilled" || !r.value.items.length) return;
    const id = defs[i][0];
    const tv = id === "recentTv" || !!(LISTS[id] && LISTS[id].tv);
    const title = id === "recent" || id === "recentTv" ? t(id) : t(LISTS[id].key);
    rows.push({ id, title, ref: "browse:" + id, items: r.value.items,
      genre: /** @type {"peliculas" | "series"} */ (tv ? "series" : "peliculas") });
  });
  if (!rows.length) {
    const failed = settled.find((r) => r.status === "rejected");
    throw failed && failed.status === "rejected" ? failed.reason : kino.error("unavailable", "empty home", { userMessage: t("noStreams") });
  }
  return rows;
}

export async function section() {
  const rows = await home();
  const first = rows[0] && rows[0].items.find((i) => i.backdrop);
  return { rows, ...(first ? { hero: { title: first.title, image: first.backdrop } } : {}) };
}

export async function browse(ref, cursor) {
  const parts = String(ref).split(":");
  if (parts[1] === "recent") return recent(cursor, PAGE, false);
  if (parts[1] === "recentTv") return recent(cursor, PAGE, true);
  const page = Math.max(1, parseInt(cursor || "1", 10) || 1);
  if (parts[1] === "genre" && /^\d+$/.test(parts[2] || "")) {
    return filtered("/discover/movie", { with_genres: parts[2], sort_by: "popularity.desc", "vote_count.gte": 20 }, page, false);
  }
  const def = LISTS[parts[1]];
  if (!def) throw kino.error("not_found", "unknown browse ref: " + ref, { userMessage: t("notFound") });
  return filtered(def.path, {}, page, !!def.tv);
}

export async function categories() {
  const data = await tmdb("/genre/movie/list");
  return (data.genres || []).slice(0, 19).map((g) => ({
    id: "g" + g.id, title: `${t("genre")} ${g.name}`.slice(0, 40), ref: "browse:genre:" + g.id,
  }));
}

export async function search(query) {
  const q = (typeof query === "string" ? query : (query && query.q) || "").trim();
  if (!q) return [];
  const y = query && typeof query === "object" && query.year ? query.year : undefined;
  const asks = [
    ...[1, 2, 3].map((page) => [false, tmdb("/search/movie", { query: q, include_adult: false, page, ...(y ? { year: y } : {}) })]),
    ...[1, 2].map((page) => [true, tmdb("/search/tv", { query: q, include_adult: false, page, ...(y ? { first_air_date_year: y } : {}) })]),
  ];
  const pages = await Promise.allSettled(asks.map(([, p]) => p));
  if (pages[0].status === "rejected" && pages[3].status === "rejected") throw pages[0].reason;
  const items = [];
  pages.forEach((r, i) => {
    if (r.status !== "fulfilled") return;
    const tv = asks[i][0];
    for (const m of r.value.results || []) {
      if (m.poster_path && (tv ? hasTv(m.id) : has(m.id))) items.push(card(slim(m, tv)));
    }
  });
  return items;
}

const parseMovieRef = (ref) => {
  const m = /^m:(i?\d+)$/.exec(String(ref || ""));
  return m ? m[1] : null;
};
const parseShowRef = (ref) => {
  const m = /^s:(\d+)$/.exec(String(ref || ""));
  return m ? m[1] : null;
};

export async function details(ref) {
  const sid = parseShowRef(ref);
  if (sid) {
    const d = await tmdb("/tv/" + sid, { append_to_response: "external_ids" });
    const imdb = d.external_ids && d.external_ids.imdb_id;
    return {
      title: d.name,
      poster: img("w500", d.poster_path),
      backdrop: img("w1280", d.backdrop_path),
      overview: d.overview || undefined,
      genres: (d.genres || []).map((g) => g.name).slice(0, 5),
      year: year(d.first_air_date),
      rating: d.vote_average ? Math.round(d.vote_average * 10) / 10 : undefined,
      ids: { tmdb: d.id, ...(/^tt\d{5,10}$/.test(imdb || "") ? { imdb } : {}) },
    };
  }
  const id = parseMovieRef(ref);
  if (!id) return null;
  const m = await movieFor(id);
  if (!m) throw kino.error("not_found", "no tmdb for " + id, { userMessage: t("notFound") });
  const d = await tmdb("/movie/" + m.id);
  return {
    title: d.title,
    poster: img("w500", d.poster_path),
    backdrop: img("w1280", d.backdrop_path),
    overview: d.overview || undefined,
    genres: (d.genres || []).map((g) => g.name).slice(0, 5),
    year: year(d.release_date),
    rating: d.vote_average ? Math.round(d.vote_average * 10) / 10 : undefined,
    runtimeMinutes: d.runtime > 0 ? d.runtime : undefined,
    ids: { tmdb: d.id, ...(/^tt\d{5,10}$/.test(d.imdb_id || "") ? { imdb: d.imdb_id } : {}) },
  };
}

/** Only the episodes in the index (those with a captcha-free copy), named and pictured by TMDB when it can. */
export async function episodes(ref) {
  const id = parseShowRef(ref);
  if (!id) throw kino.error("not_found", "not a series ref", { userMessage: t("notFound") });
  const have = showEpisodes(id);
  if (!have.size) throw kino.error("not_found", "series not in index: " + id, { userMessage: t("notFound") });
  const seasons = [...new Set([...have.keys()].map((k) => Number(k.split(".")[0])))].sort((a, b) => a - b);

  /** @type {any} */
  let show = null;
  /** @type {Map<string, any>} */
  const info = new Map();
  try {
    // append_to_response takes up to 20 sub-requests per call: the first call carries the first 19 seasons.
    show = await tmdb("/tv/" + id, { append_to_response: ["external_ids", ...seasons.slice(0, 19).map((s) => "season/" + s)].join(",") });
    const more = [];
    for (let i = 19; i < seasons.length; i += 20) more.push(seasons.slice(i, i + 20));
    const extra = await Promise.allSettled(more.map((g) => tmdb("/tv/" + id, { append_to_response: g.map((s) => "season/" + s).join(",") })));
    const blocks = [show, ...extra.filter((r) => r.status === "fulfilled").map((r) => /** @type {any} */ (r).value)];
    for (const b of blocks) {
      for (const s of seasons) {
        const sd = b["season/" + s];
        for (const ep of (sd && sd.episodes) || []) info.set(`${s}.${ep.episode_number}`, ep);
      }
    }
  } catch { /* no TMDB: the episodes still play, numbered only */ }

  const out = [];
  for (const [k, codes] of have) {
    if (!liveCodes(codes).length) continue;
    const [s, n] = k.split(".").map(Number);
    const ep = info.get(k);
    out.push({
      season: s,
      number: n,
      ref: `e:${id}:${s}:${n}`,
      title: (ep && ep.name) || `${t("episode")} ${n}`,
      still: ep ? img("w300", ep.still_path) : undefined,
      overview: (ep && ep.overview) || undefined,
      airDate: ep && /^\d{4}-\d{2}-\d{2}$/.test(ep.air_date || "") ? ep.air_date : undefined,
      runtimeMinutes: ep && ep.runtime > 0 && ep.runtime <= 1000 ? ep.runtime : undefined,
    });
  }
  out.sort((x, y) => x.season - y.season || x.number - y.number);
  if (!show) return { episodes: out };
  const imdb = show.external_ids && show.external_ids.imdb_id;
  return {
    series: {
      title: show.name,
      poster: img("w500", show.poster_path),
      backdrop: img("w1280", show.backdrop_path),
      overview: show.overview || undefined,
      genres: (show.genres || []).map((g) => g.name).slice(0, 5),
      year: year(show.first_air_date),
      rating: show.vote_average ? Math.round(show.vote_average * 10) / 10 : undefined,
      ids: { tmdb: show.id, ...(/^tt\d{5,10}$/.test(imdb || "") ? { imdb } : {}) },
    },
    episodes: out,
  };
}

// ---- 5. resolvers (captcha-free hosts only) ----

const UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36";

/** The host says the file is not there: this copy is remembered as dead. */
function goneErr(message) {
  // The flag rides in the message too, in case the runtime hands back a sealed error object.
  const e = kino.error("unavailable", "gone " + message);
  try { /** @type {any} */ (e).gone = true; } catch { /* sealed */ }
  return e;
}
const DELETED = /WE ARE SORRY|can't find the (file|video)|file (was|has been) (deleted|removed)|not found|no longer available/i;

// vidmoly answers 404 (with "not found" in the page) to an IP that asked too much, even for files it has: nothing
// it says is taken as deleted.
async function page(url, referer, trust404 = true) {
  const r = await kino.fetch(url, { headers: { "User-Agent": UA, Referer: referer }, timeoutMs: 15000 });
  if (r.status === 404) throw trust404 ? goneErr("http 404 " + url) : kino.error("unavailable", "suspect http 404 " + url);
  if (!r.ok) throw kino.error("unavailable", "http " + r.status + " " + url);
  return r.text();
}

/** vidmoly: the embed page carries the HLS master playlist. */
async function vidmoly(code) {
  const html = await page(`https://vidmoly.biz/embed-${code}.html`, "https://hdfull.org/", false);
  const m = /https?:\/\/[^"'\s]+\.m3u8[^"'\s]*/.exec(html);
  if (!m) throw kino.error("unavailable", "suspect vidmoly: no playlist for " + code);
  return {
    url: m[0],
    mime: "application/x-mpegURL",
    headers: { Referer: "https://vidmoly.biz/", Origin: "https://vidmoly.biz", "User-Agent": UA },
    expiresInSeconds: 3600,
  };
}

/** streamtape: the page builds the file URL from two string pieces (the "robotlink"). */
async function streamtape(code) {
  const html = await page(`https://streamtape.com/e/${code}`, "https://hdfull.org/");
  const all = [...html.matchAll(/robotlink'\)\.innerHTML = '([^']+)'\+ \('([^']+)'\)((?:\.substring\(\d+\))+)/g)];
  const last = all[all.length - 1];
  if (!last) throw DELETED.test(html) ? goneErr("streamtape: deleted " + code) : kino.error("unavailable", "streamtape: no robotlink for " + code);
  let tail = last[2];
  for (const n of last[3].match(/\d+/g) || []) tail = tail.slice(Number(n));
  return {
    url: "https:" + last[1] + tail + "&stream=1",
    mime: "video/mp4",
    headers: { Referer: "https://streamtape.com/", "User-Agent": UA },
    expiresInSeconds: 3600,
  };
}

/** Dean Edwards' p,a,c,k,e,d packer, undone as text (the packed code is never run). */
function unpack(html) {
  const m = /\}\('([\s\S]*?)',(\d+),(\d+),'([\s\S]*?)'\.split\('\|'\)/.exec(html);
  if (!m) return "";
  const radix = Number(m[2]);
  const words = m[4].split("|");
  const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const value = (w) => { let n = 0; for (const ch of w) n = n * radix + digits.indexOf(ch); return n; };
  return m[1].replace(/\b\w+\b/g, (w) => { const i = value(w); return words[i] || w; });
}

/** mixdrop: the packed player script sets MDCore.wurl to the MP4 (needs a User-Agent, else 403). */
async function mixdrop(code) {
  const html = await page(`https://mixdrop.bz/e/${code}`, "https://hdfull.org/");
  const m = /MDCore\.wurl\s*=\s*"([^"]+)"/.exec(unpack(html));
  if (!m) throw DELETED.test(html) ? goneErr("mixdrop: deleted " + code) : kino.error("unavailable", "mixdrop: no file for " + code);
  return {
    url: m[1].startsWith("//") ? "https:" + m[1] : m[1],
    mime: "video/mp4",
    headers: { Referer: "https://mixdrop.bz/", "User-Agent": UA },
    expiresInSeconds: 3600,
  };
}

/** True when the host answered that the file is not there (not a network or rate-limit failure). */
const gone = (e) => !!(e && (e.gone || /^gone /.test(String(e.message || ""))));
/** True when vidmoly showed no playlist: deleted or blocked, it cannot tell which. */
const suspect = (e) => /^suspect /.test(String((e && e.message) || ""));
function play(slot) {
  const host = slot[1];
  const code = slot.slice(2);
  if (!/^[A-Za-z0-9]{6,40}$/.test(code)) throw kino.error("invalid_request", "bad code " + slot);
  if (host === "v") return vidmoly(code);
  if (host === "s") return streamtape(code);
  if (host === "m") return mixdrop(code);
  throw kino.error("invalid_request", "unknown host " + slot);
}

const HOST_NAMES = { v: "Vidmoly", s: "Streamtape", m: "Mixdrop" };
const label = (slot) => `${T[isEs() ? "es" : "en"].lang[slot[0]] || slot[0]} · ${HOST_NAMES[slot[1]] || slot[1]}`;

// ---- 6. resolve ----

/** Codes of one title, the preferred language first, vidmoly (HLS) before streamtape and mixdrop within a language. */
function ranked(codes) {
  const pref = String(cfg("audio", "E"));
  const score = (c) => (c[0] === pref ? 0 : 10) + "ELSO".indexOf(c[0]) + ({ v: 0, s: 0.3, m: 0.6 }[c[1]] || 0.9);
  return [...codes].sort((a, b) => score(a) - score(b));
}

/** The codes behind a movie or episode ref, or null. */
function codesFor(ref) {
  const ep = /^e:(\d+):(\d+):(\d+)$/.exec(ref);
  if (ep) return showEpisodes(ep[1]).get(`${Number(ep[2])}.${Number(ep[3])}`) || null;
  const id = parseMovieRef(ref);
  return id ? index().get(id) || null : null;
}

export async function resolve(ref) {
  const s = String(ref || "");
  const lazy = /^c:([ELSO][vsm][A-Za-z0-9]{6,40})$/.exec(s);
  if (lazy) {
    try { const st = await play(lazy[1]); notePlayed(lazy[1]); return st; } catch (e) {
      noteFailure(lazy[1], e);
      throw kino.error("unavailable", "copy failed", { userMessage: t("noStreams") });
    }
  }
  const codes = codesFor(s);
  if (!codes || !codes.length) throw kino.error("not_found", "not in index: " + s, { userMessage: t("notFound") });
  const list = ranked(liveCodes(codes));
  for (let i = 0; i < Math.min(list.length, 4); i++) {
    let stream;
    try { stream = await play(list[i]); notePlayed(list[i]); } catch (e) { noteFailure(list[i], e); continue; }
    const rest = list.filter((_, j) => j !== i);
    return { ...stream, alternatives: rest.map((c) => ({ label: label(c), ref: "c:" + c })) };
  }
  throw kino.error("unavailable", "no copy loaded for " + s, { userMessage: t("noStreams") });
}

// ---- settings status ----

export async function settingsStatus(key) {
  if (key !== "indexStatus") return { text: "?", textEn: "?" };
  const m = index().size;
  const tv = tvIndex();
  let e = 0;
  for (const raw of tv.values()) e += raw.split(";").length;
  return { text: T.es.status(m, tv.size, e), textEn: T.en.status(m, tv.size, e) };
}
